use std::path::Path;
use std::process::exit;

use crate::messages::{push_message, Type};

/// Start a web server to preview the generated blog
pub async fn serve(port: u16) {
    if !Path::new("public").exists() {
        push_message(
            Type::Error,
            "Make sure you're running `serve` in your blog's directory \
            and the `public` directory has been generated, if not, use the `build` command.",
        );
        exit(1)
    }

    push_message(
        Type::Success,
        &format!("Gisture server is running on http://127.0.0.1:{}/ 🚀", port),
    );

    if portpicker::is_free(port) {
        warp::serve(warp::fs::dir("public"))
            .run(([127, 0, 0, 1], port))
            .await;
    } else {
        let message = format!("PORT {} is not free.", port);
        push_message(Type::Error, &message);
        exit(1)
    }
}

use colored::*;

/// Logging message types
pub enum Type {
    Warning,
    Error,
    Info,
    Success,
}

/*
    should've just used `https://github.com/dtolnay/thiserror` or something, but it's "not bad" okay?
    I wanted this format on messages to provide a CLI experience that doesn't look like stack traces
    and it's just some `Ok`, `Err`, `exit(1)` over and over again... yeah.
*/

/// Outputs logging messages
pub fn push_message(log_type: Type, message: &str) {
    let prefix = match log_type {
        Type::Warning => format!("{}{}{}", "[".bold(), "WARN".bold().yellow(), "]".bold()),
        Type::Error => format!("{}{}{}", "[".bold(), "ERROR".bold().red(), "]".bold()),
        Type::Info => format!("{}{}{}", "[".bold(), "INFO".bold().cyan(), "]".bold()),
        Type::Success => format!("{}{}{}", "[".bold(), "SUCCESS".bold().green(), "]".bold())
    };

    eprintln!("{}", format!("{} {}", prefix, message))
}

use std::path::Path;

use cacache;

#[derive(Debug, Clone)]
pub(crate) struct Cache {
    pub permalink_key: String,
    pub updated_at: String,
}

// NOTE: cache function calls are blocking (forced sync)
impl Cache {
    /// Save a blog entry to disk cache
    pub async fn save_cache_entry(&self) -> Result<(), cacache::Error> {
        let cache_dir = String::from("./gisture_cache");

        cacache::write(&cache_dir, &self.permalink_key, self.updated_at.as_bytes()).await?;

        Ok(())
    }

    /// Check if a blog entry is cached on disk
    pub async fn is_cached(&self) -> Result<bool, cacache::Error> {
        let cache_dir = String::from("./gisture_cache");
        let data = cacache::read(&cache_dir, &self.permalink_key).await?;

        let build_file = Path::new(&format!("public/{}", &self.permalink_key)).exists();

        if data == self.updated_at.as_bytes() && build_file {
            Ok(true)
        } else {
            Ok(false)
        }
    }
}

use clap::ArgMatches;

use crate::{
    config::Config,
    gist::GistApi,
    messages::{push_message, Type},
    metadata::Utils,
    serve,
    template::TemplateWriter,
};

use std::process::exit;

pub async fn init(args: ArgMatches<'_>) {
    // set up config
    Config::generate_default();
    TemplateWriter::generate_boilerplate();

    push_message(Type::Info, "Setting up configuration files and boilerplate templates.");

    // get user command
    let feature: Option<&str> = args.value_of("COMMAND");

    match feature {
        Some("build") => {
            let page_map = GistApi::get_all_blogs();
            let config = Config::get_config();

            TemplateWriter::render_templates(&page_map);
            Utils::generate_site_metadata(&page_map, &config);

            push_message(Type::Success, "Your gisture blog is ready to ship. 🚀")
        }
        Some("serve") => {
            let port: u16 = match args.value_of("PORT") {
                Some(port) => match port.parse::<u16>() {
                    Ok(port) => port,
                    Err(_) => {
                        push_message(Type::Error, "PORT should be a number.");
                        exit(1)
                    }
                },
                None => {
                    let port = portpicker::pick_unused_port().expect("No ports free");
                    let message = format!(
                        "PORT was not provided (picked a random free port: {}).",
                        port
                    );
                    push_message(Type::Warning, &message);
                    port
                }
            };
            // `async` just for the serve...
            serve::serve(port).await
        }
        _ => {
            push_message(Type::Info, "Change the username and metadata in `gisture.json` to get started.");
            push_message(Type::Info, "The `templates` directory contains a basic starter template for your blog, customize it to your own needs.");
            push_message(Type::Warning, "Expected command `build` or `serve`.")
        }
    }
}

use std::fs::File;
use std::io::prelude::*;
use std::io::BufReader;
use std::path::Path;
use std::process::exit;

use serde::{Deserialize, Serialize};

use crate::messages::{push_message, Type};

#[derive(Serialize, Deserialize)]
pub(crate) struct Config {
    pub github_username: String,
    pub blog_title: String,
    pub blog_description: String,
    pub blog_url: String,
    pub pages_title: String,
    pub minify_html: bool,
    pub show_comments: bool,
}

static CONFIG_FILE: &str = "gisture.json";

impl Config {
    pub fn default() -> Self {
        // default config file values
        Self {
            github_username: "octocat".into(),
            blog_title: "John Wick's Pencil".into(),
            blog_description: "Rusty, I Guess.".into(),
            blog_url: "https://blog.johnwickspencil.com/".into(),
            pages_title: "{{ blog_title }} | John Wick's Pencil".into(),
            minify_html: false,
            show_comments: true,
        }
    }

    /// Generate a boilerplate config file
    pub fn generate_default() {
        if !Path::new(CONFIG_FILE).exists() {
            let json_config = match serde_json::to_string_pretty(&Self::default()) {
                Ok(json_config) => json_config,
                Err(error) => {
                    let message = format!("Failed to serialize JSON config: \n\t{}", error);
                    push_message(Type::Error, &message);
                    exit(1)
                }
            };
            let mut config_file = match File::create(CONFIG_FILE) {
                Ok(file) => file,
                Err(error) => {
                    let message = format!("Failed to create config file: \n\t{}", error);
                    push_message(Type::Error, &message);
                    exit(1)
                }
            };
            match config_file.write_all(json_config.as_bytes()) {
                Ok(()) => (),
                Err(error) => {
                    let message = format!("Failed to write to config file: \n\t{}", error);
                    push_message(Type::Error, &message);
                    exit(1)
                }
            }
        }
    }

    /// Fetch config values from `gisture.json`
    pub fn get_config() -> Self {
        let file = match File::open(CONFIG_FILE) {
            Ok(file) => file,
            Err(error) => {
                let message = format!("Failed to open config file: \n\t{}", error);
                push_message(Type::Error, &message);
                exit(1)
            }
        };

        let mut buf_reader = BufReader::new(file);
        let mut user_config = String::new();
        match buf_reader.read_to_string(&mut user_config) {
            Ok(_) => (),
            Err(error) => {
                let message = format!("Failed while reading config file: \n\t{}", error);
                push_message(Type::Error, &message);
                exit(1)
            }
        }

        let config: Config = match serde_json::from_str(&user_config) {
            Ok(config) => config,
            Err(error) => {
                let message = format!("Failed while serializing user config: \n\t{}", error);
                push_message(Type::Error, &message);
                exit(1)
            }
        };

        config
    }
}

use std::collections::HashMap;
use std::fs::File;
use std::io::prelude::*;
use std::process::exit;

use sitemap::structs::UrlEntry;
use sitemap::writer::SiteMapWriter;

use chrono::prelude::*;

use crate::{
    config::Config,
    gist::GistPage,
    messages::{push_message, Type},
    parsers::ParserUtils,
};

pub(crate) struct Utils;

impl Utils {
    pub fn generate_site_metadata(page_map: &HashMap<String, GistPage>, config: &Config) {
        Self::generate_robots_txt(config);
        Self::generate_sitemap(page_map, config);
    }

    /// Generate a robots.txt file for search engine crawlers (SEO)
    fn generate_robots_txt(config: &Config) {
        let robots_txt = format!(
            "User-agent: Mediapartners-Google\nDisallow:\n\nUser-agent: *\nAllow: /\n\nSitemap: {}",
            ParserUtils::join_url_path(&config.blog_url, "sitemap.xml")
        );

        let mut robots_file = match File::create("public/robots.txt") {
            Ok(file) => file,
            Err(error) => {
                let message = format!("Failed to create `robots.txt` file due to: \n\t{}", error);
                push_message(Type::Error, &message);
                exit(1)
            }
        };

        match robots_file.write_all(robots_txt.as_bytes()) {
            Ok(()) => (),
            Err(error) => {
                let message = format!("Failed to write `robots.txt` file due to: \n\t{}", error);
                push_message(Type::Error, &message);
                exit(1)
            }
        }
    }

    /// Generate a XML sitemap of the blog structure (SEO)
    fn generate_sitemap(page_map: &HashMap<String, GistPage>, config: &Config) {
        let mut sitemap_xml_buffer = match File::create("public/sitemap.xml") {
            Ok(buffer) => buffer,
            Err(error) => {
                let message = format!("Failed to create `sitemap.xml` file due to: \n\t{}", error);
                push_message(Type::Error, &message);
                exit(1)
            }
        };

        let sitemap_writer = SiteMapWriter::new(&mut sitemap_xml_buffer);
        let mut urlwriter = match sitemap_writer.start_urlset() {
            Ok(urlwriter) => urlwriter,
            Err(error) => {
                let message = format!(
                    "Failed to write `urlset` to `sitemap.xml` file due to: \n\t{}.",
                    error
                );
                push_message(Type::Error, &message);
                exit(1)
            }
        };

        let blog_url = &config.blog_url;

        // write blog index url
        match urlwriter.url(blog_url.clone()) {
            Ok(()) => (),
            Err(_) => {
                push_message(
                    Type::Error,
                    "Failed to write `blog_url` from config to `sitemap.xml`.",
                );
                exit(1)
            }
        }

        for (page, page_data) in page_map {
            let lastmod_datetime = match page_data.updated_at.parse::<DateTime<FixedOffset>>() {
                Ok(parsed) => parsed,
                Err(error) => {
                    let message = format!(
                        "Failed to parse `{}` to `DateTime` format due to: \n\t{}.",
                        page_data.updated_at, error
                    );
                    push_message(Type::Error, &message);
                    exit(1)
                }
            };

            let url_builder = match UrlEntry::builder()
                .loc(ParserUtils::join_url_path(&blog_url, page))
                .lastmod(lastmod_datetime)
                .build()
            {
                Ok(url_builder) => url_builder,
                Err(error) => {
                    let message = format!("Failed to build `sitemap.xml` due to: \n\t{}", error);
                    push_message(Type::Error, &message);
                    exit(1)
                }
            };

            match urlwriter.url(url_builder) {
                Ok(()) => (),
                Err(error) => {
                    let message = format!(
                        "Failed to write `{}` to URL set of `sitemap.xml` due to: \n\t{}.",
                        page, error
                    );
                    push_message(Type::Error, &message);
                    exit(1)
                }
            }
        }

        match urlwriter.end() {
            Ok(_) => (),
            Err(error) => {
                let message = format!(
                    "Failed to close tags for `sitemap.xml` due to: \n\t{}.",
                    error
                );
                push_message(Type::Error, &message);
                exit(1)
            }
        }
    }
}

use once_cell::sync::Lazy;
use std::collections::HashMap;
use std::process::exit;

use pulldown_cmark::{html, Options, Parser};

use syntect::highlighting::ThemeSet;
use syntect::html::highlighted_html_for_string;
use syntect::parsing::SyntaxSet;

use html_escape::{encode_text, decode_html_entities};
use lol_html::html_content::ContentType;
use lol_html::{rewrite_str, text, RewriteStrSettings};

use crate::messages::{push_message, Type};

pub(crate) struct ParserUtils;

impl ParserUtils {
    /// Highlight source code snippets in the parsed HTML
    fn highlight_source_code(html: &str) -> String {
        let mut lang_set: Vec<String> = Vec::new();

        // the lazy but quick html parsing
        for segment in html.split("\n") {
            if segment.contains("<code class=\"language-") {
                for item in segment.split("\"") {
                    if item.contains("language") {
                        lang_set.push(item.replace("language-", ""));
                    }
                }
            } else if segment.contains("<code>") {
                lang_set.push("txt".into())
            }
        }

        if lang_set.len() != 0 {
            static SYNTAX_SET: Lazy<SyntaxSet> = Lazy::new(|| {
                let mut syntax_set = SyntaxSet::load_defaults_newlines().into_builder();
                syntax_set.add_from_folder("syntaxes", true).ok();
                syntax_set.build()
            });

            let theme_set = ThemeSet::load_defaults();
            let theme = &theme_set.themes["InspiredGitHub"];

            let mut code_elem_idx = 0;

            let rewrite = match rewrite_str(
                &html.replace("&quot;", "\""),
                RewriteStrSettings {
                    element_content_handlers: vec![text!("code", |chunk| {
                        if code_elem_idx > lang_set.len() - 1 {
                            let escape = encode_text(chunk.as_str()).to_string();
                            chunk.replace(&escape, ContentType::Text)
                        } else {
                            let lang_syntax =
                                match SyntaxSet::find_syntax_by_token(&SYNTAX_SET, &lang_set[code_elem_idx]) {
                                    Some(lang_syntax) => lang_syntax,
                                    None => {
                                        let message = format!(
                                            "No syntax highlighting spec found for `{}`.",
                                            &lang_set[code_elem_idx]
                                        );
                                        push_message(Type::Warning, &message);
                                        match SyntaxSet::find_syntax_by_token(&SYNTAX_SET, "txt") {
                                            Some(lang_syntax) => lang_syntax,
                                            _ => unreachable!()
                                        }
                                    }
                                };

                            chunk.replace(
                                &highlighted_html_for_string(
                                    &chunk.as_str(),
                                    &SYNTAX_SET,
                                    lang_syntax,
                                    theme,
                                ),
                                ContentType::Text,
                            );
                        };

                        code_elem_idx += 1;

                        Ok(())
                    })],
                    ..RewriteStrSettings::default()
                },
            ) {
                Ok(rewrite) => rewrite,
                Err(error) => {
                    let message = format!(
                        "Failed to highlight syntax inside HTML document due to: \n\t{}",
                        error
                    );
                    push_message(Type::Error, &message);
                    exit(1)
                }
            };

            // return a sanitized output
            // is there a better way to go about this? i suck at html.
            decode_html_entities(&rewrite)
                .replace("&amp;", "&") // encoding lives happily ever after
                .replace("<pre style=\"background-color:#ffffff;\">\n</pre>", "") // anomaly
                .replace("<code><pre style=\"background-color:#ffffff;\">", "<code>") // next anomaly
        } else {
            html.to_string()
        }
    }

    /// Converts gist's raw markdown to HTML
    pub fn parse_markdown_to_html(raw_markdown: String) -> String {
        static OPTIONS: Lazy<pulldown_cmark::Options> = Lazy::new(|| {
            let mut options = Options::empty();
            options.insert(Options::ENABLE_STRIKETHROUGH);
            options.insert(Options::ENABLE_TABLES);
            options.insert(Options::ENABLE_SMART_PUNCTUATION);
            options.insert(Options::ENABLE_FOOTNOTES);
            options.insert(Options::ENABLE_TASKLISTS);
            options
        });

        let parser = Parser::new_ext(&raw_markdown, *OPTIONS);
        let mut html_output = String::new();
        html::push_html(&mut html_output, parser);

        Self::highlight_source_code(&html_output)
    }

    /// For handling trailing slashes on URLs
    pub fn join_url_path(url: &str, path: &str) -> String {
        if url.ends_with("/") {
            format!("{}{}", url, path)
        } else {
            format!("{}/{}", url, path)
        }
    }

    /// RFC 3339 date-time parsing and sorting
    pub fn _sort_by_date(_page_metadata: HashMap<String, String>) -> HashMap<i32, String> {
        /*
            This is not required atm because gist already outputs a sorted list.
            It's in descending order so we just traverse the list in reverse.
            If anyone asks for sorting configurations for their blog listing or
            the gist fetching goes multi-threaded this will be implemented.
        */
        unimplemented!();
    }
}

use std::collections::HashMap;
use std::process::exit;
use std::time::Duration;

use serde_json::{Map, Value};
use ureq::{Agent, AgentBuilder};

use crate::{
    config::Config,
    messages::{push_message, Type},
    parsers::ParserUtils,
};

#[derive(Debug, Clone)]
pub(crate) struct GistPage {
    pub title: String,
    pub description: String,
    pub created_at: String,
    pub updated_at: String,
    pub content: String,
    pub html_url: String,
}

pub(crate) struct GistApi;

impl GistApi {
    /// Fetch user's gist entries
    fn get_user_gists(conn_pool: &Agent) -> Vec<Value> {
        let username = Config::get_config().github_username;
        let endpoint = format!("https://api.github.com/users/{}/gists", username);
        let user_gists: String = match conn_pool
            .get(&endpoint)
            .set("Accept", "application/vnd.github.v3+json")
            .call()
        {
            Ok(response) => match response.into_string() {
                Ok(json_response) => json_response,
                Err(error) => {
                    let message = format!(
                        "Failed while encoding response from Gist API: \n\t{}",
                        error
                    );
                    push_message(Type::Error, &message);
                    exit(1);
                }
            },
            Err(error) => {
                let message = format!("Couldn't send HTTP request to Gist API: \n\t{}", error);
                push_message(Type::Error, &message);
                exit(1);
            }
        };

        match serde_json::from_str(&user_gists) {
            Ok(gist_vec) => gist_vec,
            Err(error) => {
                let message = format!(
                    "Failed to serialize JSON response from Gist API: \n\t{}",
                    error
                );
                push_message(Type::Error, &message);
                exit(1);
            }
        }
    }

    /// Fetch raw markdown for a particular gist entry
    fn get_gist_markdown(conn_pool: &Agent, url: &str) -> String {
        match conn_pool.get(url).call() {
            Ok(response) => match response.into_string() {
                Ok(markdown) => markdown,
                Err(error) => {
                    let message = format!(
                        "Failed while encoding response from Gist API: \n\t{}",
                        error
                    );
                    push_message(Type::Error, &message);
                    exit(1);
                }
            },
            Err(error) => {
                let message = format!("Couldn't send HTTP request to Gist API: \n\t{}", error);
                push_message(Type::Error, &message);
                exit(1);
            }
        }
    }

    /// Organize a blog map of all gist entries
    pub fn get_all_blogs() -> HashMap<String, GistPage> {
        push_message(Type::Info, "Fetching gist schema.");

        // register a ureq agent (connection pool)
        let conn_pool: Agent = AgentBuilder::new()
            .timeout_read(Duration::from_secs(5))
            .timeout_write(Duration::from_secs(5))
            .build();

        let user_gists = Self::get_user_gists(&conn_pool);

        // to store all blog's permalink and their contents
        let mut blogs: HashMap<String, GistPage> = HashMap::new();

        for gist in user_gists {
            let gist_files: Map<String, Value> =
                match serde_json::from_str(&gist["files"].to_string()) {
                    Ok(gist_files) => gist_files,
                    Err(error) => {
                        let message =
                            format!("Failed while scraping files inside Gist: \n\t{}", error);
                        push_message(Type::Error, &message);
                        exit(1);
                    }
                };

            for (file, metadata) in gist_files {
                // gisture files should end with `blog.md`, this is to distinguish from other gists
                if file.ends_with("blog.md") {
                    // url to get the the raw markdown
                    let raw_url = metadata["raw_url"].to_string().replace("\"", "");

                    // get raw markdown of gist
                    let markdown_content = Self::get_gist_markdown(&conn_pool, &raw_url);

                    // parse blog title from markdown (`# Title`)
                    let page_title = match markdown_content.split("\n").nth(0) {
                        Some(title) => {
                            if title.contains("#") {
                                title.replace("#", "").trim().to_string()
                            } else {
                                let message = format!("Gist `{}` doesn't contain a title (`# Title`) on top. (SKIPPED)", file);
                                push_message(Type::Warning, &message);
                                continue;
                            }
                        }
                        None => {
                            let message = format!("Encountered empty Gist: `{}` (SKIPPED)", file);
                            push_message(Type::Warning, &message);
                            continue;
                        }
                    };

                    // permalink is the filename without the gisture markdown extension
                    let permalink = file.replace(".blog.md", "");

                    // convert gist Markdown to HTML
                    let html_content = ParserUtils::parse_markdown_to_html(markdown_content);

                    let page_data: GistPage = GistPage {
                        title: page_title,
                        description: gist["description"].to_string().replace("\"", ""),
                        created_at: gist["created_at"].to_string().replace("\"", ""),
                        updated_at: gist["updated_at"].to_string().replace("\"", ""),
                        html_url: gist["html_url"].to_string().replace("\"", ""),
                        content: html_content,
                    };

                    // save blog with it's raw markdown
                    blogs.insert(permalink, page_data);

                    let message = format!("Fetched blog \"{}\".", file);
                    push_message(Type::Info, &message);
                }
            }
        }

        // if there are no gisture blogs, why should I live any longer?
        if blogs.len() == 0 {
            let username = Config::get_config().github_username;
            let message = format!("0 gisture blogs (*.blog.md) found for user '{}'", username);
            push_message(Type::Warning, &message);
            exit(0)
        }

        blogs
    }
}

use std::collections::HashMap;
